def digit_sum_persistence_base(n, b):
    count = 0
    while n >= b:
        total = 0
        while n > 0:
            total += n % b
            n //= b
        n = total
        count += 1
    return count

def longest_run_length(lst):
    if len(lst) == 0:
        return 0
    longest = 1
    current = 1
    for i in range(1, len(lst)):
        if lst[i] == lst[i - 1]:
            current += 1
            if current > longest:
                longest = current
        else:
            current = 1
    return longest

def count_distinct_rotations(lst):
    n = len(lst)
    if n == 0:
        return 1
    rotations = set()
    for shift in range(n):
        rotated = tuple(lst[shift:] + lst[:shift])
        rotations.add(rotated)
    return len(rotations)

