def is_valid_subnet_mask(s):
    octets = s.split('.')
    if len(octets) != 4:
        return False
    values = []
    for o in octets:
        if not o.isdigit():
            return False
        v = int(o)
        if v > 255:
            return False
        values.append(v)
    bitstring = ''
    for v in values:
        bitstring += format(v, '08b')
    seen_zero = False
    for bit in bitstring:
        if bit == '0':
            seen_zero = True
        elif bit == '1' and seen_zero:
            return False
    return True

