def is_valid_binary_fraction(s):
    if s.count('.') != 1:
        return False
    int_part, frac_part = s.split('.')
    if len(int_part) == 0 or len(frac_part) == 0:
        return False
    for ch in int_part + frac_part:
        if ch not in ('0', '1'):
            return False
    return True

