def wrap_and_count(text, width):
    words = text.split()
    if not words:
        return 0
    line_count = 1
    current_len = len(words[0])
    for word in words[1:]:
        if current_len + 1 + len(word) <= width:
            current_len += 1 + len(word)
        else:
            line_count += 1
            current_len = len(word)
    return line_count

def find_repeated_words(s):
    words = s.split()
    seen_order = []
    counts = {}
    for w in words:
        low = w.lower()
        if low not in counts:
            counts[low] = 0
            seen_order.append(low)
        counts[low] += 1
    return [w for w in seen_order if counts[w] >= 2]

def sort_by_distance_from_target_farthest_first(nums, target):
